using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using VisualQa.Core;
namespace VisualQa.WpfCapture;
public sealed class WpfMetadataCollector { public RuntimeComponentSnapshot Collect(FrameworkElement root,string name) { root.UpdateLayout();var elements=new List<RuntimeElementSnapshot>();Walk(root,root,elements);return new(){Name=name,Platform="wpf",Width=root.ActualWidth,Height=root.ActualHeight,DpiX=VisualTreeHelper.GetDpi(root).PixelsPerInchX,DpiY=VisualTreeHelper.GetDpi(root).PixelsPerInchY,Environment=new(Environment.OSVersion.ToString(),Environment.Version.ToString(),VisualTreeHelper.GetDpi(root).DpiScaleX,"WPF"),Elements=elements}; }
 void Walk(DependencyObject current,FrameworkElement root,List<RuntimeElementSnapshot> output) { if(current is FrameworkElement e&&!string.IsNullOrWhiteSpace(VisualQa.GetId(e))){var p=e.TransformToAncestor(root).Transform(new Point());var margin=e.Margin;var padding=e is Control c?c.Padding:new Thickness();output.Add(new(){Id=VisualQa.GetId(e),Type=e.GetType().Name,Bounds=new(p.X,p.Y,e.ActualWidth,e.ActualHeight),Text=e is TextBlock text?text.Text:e is ContentControl content?content.Content?.ToString():null,FontFamily=e is Control fc?fc.FontFamily.Source:e is TextBlock ft?ft.FontFamily.Source:null,FontSize=e is Control cs?cs.FontSize:e is TextBlock ts?ts.FontSize:null,FontWeight=e is Control cw?cw.FontWeight.ToString():e is TextBlock tw?tw.FontWeight.ToString():null,ForegroundColor=Color(e is Control fgc?fgc.Foreground:e is TextBlock fgt?fgt.Foreground:null),BackgroundColor=Color(e is Control bg?bg.Background:null),Margin=new(margin.Top,margin.Right,margin.Bottom,margin.Left),Padding=new(padding.Top,padding.Right,padding.Bottom,padding.Left),IsVisible=e.IsVisible});}for(var i=0;i<VisualTreeHelper.GetChildrenCount(current);i++)Walk(VisualTreeHelper.GetChild(current,i),root,output); }
 static string? Color(Brush? brush)=>brush is SolidColorBrush b?$"#{b.Color.R:X2}{b.Color.G:X2}{b.Color.B:X2}":null; }
